        _defaultSpellsRecord(name.isNotEmpty ? name : rawKind, explicitUrl);
    final spec = resolveCliProviderSpec(
      name.isNotEmpty ? name : rawKind,
      baseUrl: defaultSpelling ? null : baseUrl,
    );
