const _translatedSse = '''
event: message_start
data: {"type":"message_start","message":{"id":"msg_bifrost","usage":{"input_tokens":10,"output_tokens":1}}}

event: content_block_start
data: {"type":"content_block_start","index":0,"content_block":{"type":"text","text":""}}

