    apiKey = [REDACTED:Sensitive Value];
  }

  return EnvProviderPreconfig(
    spec: spec,
    name: name,
    baseUrl: config.values['baseUrl']!,
    modelId: config.values['model']!,
    apiKeyEnvVar: keyVar,
